--header 'Authorization: Bearer YOUR_API_KEY' \
--header 'Accept-Language: en-US,en' \
--header 'Content-Type: application/json' \
--data '{
"model": "glm-5.3",
"messages": [
{
"role": "system",
"content": "You are a professional programming assistant"
},
{
"role": "user",
